      color: 10181046
    }
  }
];

const item = $input.item.json;
const topicName = item.name;
const subtopics = item.subtopics || [];
const count = item.count || 3;

const subtopicsList = subtopics.map(s => `- ${s}`).join("\n");

const requestBody = {
  model: "sonar",
  search_recency_filter: "week",
  messages: [
    {
      role: "system",
      content: "Du bist ein deutschsprachiger News-Kurator. Berichte präzise und faktisch auf Deutsch. Verwende ausschließlich Quellen der letzten 7 Tage."
    },
    {
      role: "user",
      content: `Finde die ${count} wichtigsten Neuigkeiten der letzten Woche im Bereich "${topicName}".\n\nPflicht: Mindestens 1 News pro Subtopic:\n${subtopicsList}\n\nSuche danach eine skurrile oder witzige Nachricht aus dem Bereich "${topicName}" der letzten Woche.\n\nFormat – exakt so:\n● **[Schlagzeile]**: [2-3 Sätze mit konkreten Fakten]\n\nFür den skurrilen/lustigen Eintrag als letztes:\n● 🎭 **[Schlagzeile]**: [2-3 Sätze]\n\nNur die ${count + 1} Bullet Points ausgeben, keine Einleitung, kein Fazit.`
    }
  ]
};

return {
  json: {
    body: JSON.stringify(requestBody)
  }
};

const response = $input.item.json;
let digestText = response.choices[0].message.content;
const citations = response.citations || [];

const lines = digestText.split("\n");
const result = [];

for (const line of lines) {
  if (line.trim().startsWith("●")) {
    const refs = [...line.matchAll(/\[(\d+)\]/g)];
    const cleanLine = line.replace(/\[\d+\]/g, "").trim();
    result.push(cleanLine);
    if (refs.length > 0) {
      const idx = parseInt(refs[0][1]) - 1;
      if (citations[idx]) {
        result.push(`[📖 Artikel lesen](${citations[idx]})`);
      }
    }
    result.push("");
  } else {
    result.push(line.replace(/\[\d+\]/g, ""));
  }
}

digestText = result.join("\n").replace(/\n{3,}/g, "\n\n").trim();

const topicName = $("Split in Batches").item.json.name;
const color = $("Split in Batches").item.json.color;
const webhookUrl = $("Split in Batches").item.json.webhook_url;

const now = new Date();
const monday = new Date(now);
const dayOfWeek = now.getDay();
const diffToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
monday.setDate(now.getDate() - diffToMonday);
const weekStart = monday.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit" });
const weekEnd = now.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric" });

const payload = {
  embeds: [{
    title: `📰 ${topicName} – Wochenrückblick ${weekStart}–${weekEnd}`,
    description: digestText,
    color: color,
    footer: { text: `Powered by Perplexity AI (Sonar) • Wöchentlicher Digest` }
  }]
};

return {
  json: {
    webhookUrl: webhookUrl,
    body: JSON.stringify(payload)
  }
};

